tool_input.new_string:
methods: {
  navMetaIcon(menu) {
    const raw = menu?.meta?.icon || menu?.icon || ''
    const icon = typeof raw === 'string' ? raw.trim() : ''
    if (!icon) return ''
    if (/^(https?:)?\/\//i.test(icon) || /^data:image\//i.test(icon)) return icon
    if (/^\/(assets|api)\//i.test(icon)) return this.resolveServerAssetUrl(icon)
    return ''
  },
  navIconHref(menu) {
    const key = resolveNavbarIconKey(menu?.meta?.title)
    return this.isActive(menu.path) ? `${key}-filled` : key
  },
  resolveServerAssetUrl,
